import {goTo, Outcome} from 'play';

export default async function main() {
  // exponential backoff on transient failures only; a refused trip is returned at once.
  // 6 attempts in all (initial + 5 retries): waits 1, 2, 4, 8, 16 seconds.
  const sleep = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));

  let trip: Outcome<unknown> = await goTo('sol_belt');
  let waitMs = 1000; // 1 second for the first retry
  for (let attempt = 1; attempt < 6; attempt++) {
    if (trip.status !== 'failed') return trip; // done, refused or partial: no retry
    await sleep(waitMs);
    waitMs *= 2;
    trip = await goTo('sol_belt');
  }
  return trip;
}
