import {orient, goTo, salvage, sell, stow, note, type Outcome} from 'play';

export default async function main() {
  // Where we are and what this place looks like; salvage knows its own location.
  const here = await orient();

  // First pass at the wrecks where we stand.
  const first = await salvage();

  // If the world says no, there is nothing to do: say so and stop with that Outcome.
  if (first.status === 'refused') {
    note(`no wreck — ${first.why}`);
    return first;
  }

  // Otherwise it landed. If it stopped part-way because the hold filled,
  // carry the take home, sell it all, come back, and look for more.
  if (first.status === 'partial' && /full|hold/i.test(first.why ?? '')) {
    // Make the room by shipping the take to the station.
    const back = await goTo('sol_station');
    if (back.status !== 'done') return back;

    // Sell everything the salvage gained, out of the hold, by name.
    const take = first.gained.items ?? [];
    const sold = await sell(take);
    if (sold.status === 'refused') {
      // Nothing sold here either — report it, and return the take's Outcome as the last one.
      note(`sold nothing at sol_station — ${sold.why}`);
      return sold;
    }

    // Come back to where the wrecks are and salvage one more time.
    const ret = await goTo('sol_debris');
    if (ret.status !== 'done') return ret;

    const again = await salvage();
    if (again.status === 'refused') {
      note(`no wreck — ${again.why}`);
      return again;
    }
    return again;
  }

  // A clean finish — nothing more to do.
  return first;
}
