import {goTo, hunt, disengage, outcome, note} from 'play';
import type {Outcome} from 'play';

export default async function main() {
  let last: Outcome<unknown>;   // the hunt's Outcome, once we got one; else undefined

  try {
    // 1 — fly to the nebula. `sol_nebula` is a POI id, so we reach it undocked, where we'll
    //    stand; `hunt` with no poi then fights where we are. A broken flight (out of fuel,
    //    refused) is a *space* state, so it is safe to hand back — the ship is not in battle.
    const flight = await goTo('sol_nebula');
    if (flight.status !== 'done') return flight;

    // 2 — the hunt itself. Whatever it ends in — done, refused, or the ship held mid-battle
    //    with the quarry still firing — `disengage` below runs after it, in every case.
    const h = await hunt({fights: 2});
    last = h;
    if (h.status === 'done') return h;   // a clean done hunt; the break-off below then no-ops
  } catch (err) {
    note(`thrown before the hunt completed: ${String(err)}; disengaging anyway`);
    // last stays undefined; the catch is the documented "thrown error" case, and the
    // guaranteed break-off below still runs, which is the whole point of swallowing it here.
  }

  // 3 — the guarantee. This runs on every path that does not return above: a refused or failed
  //    hunt (ship possibly locked in_battle) and a thrown error alike. `disengage` breaks off
  //    whatever battle holds the ship (flee, then brace if it cannot get away) and waits until
  //    the battle has actually ended; it is a safe no-op when we are not in one.
  await disengage();

  // 4 — return the hunt's Outcome, or a reported one when the throw left us without it.
  return last ?? outcome(
    `threw in flight to sol_nebula or during the 2-fight hunt (${String(err ?? 'unknown')}); broke off from the battle`
  );
