export default async function main(): Promise<Outcome<unknown>> {
  // Fly to sol_belt. A failed trip can be transient, so retry it with exponential
  // backoff (1s, 2s, 4s, 8s, 16s) — 5 retries, 6 attempts in all. A refused trip is
