    const copper = trip.detail.settled.filter(r => r.item_id === 'copper_ore');
    if (copper.length) await sell(copper, {from: 'store'});

    // Service the ship.
    serviceOut = await service();

    // Complete missions; a not-done result there is fine.
    await completeMissions();
  } catch {
    serviceOut = service() as unknown as Outcome<unknown>;
  }

  // Whatever happened, the last thing the program does is note current credits.
  await finalNote();
