import {goTo, note, Outcome} from 'play';

// One attempt at the trip. `goTo` answers a single Outcome: `done` reached it,
// `partial` started but stopped short (work done), `refused` the rules said no,
// `failed` broke mid-way or the reply was lost.
async function tryGoTo(dest: string): Promise<Outcome> {
  return goTo(dest);
}

// The trip is allowed to fail *transiently* — a flaky leg, a lost reply — and then recover.
// A `refused` is not transient: the rules or the game said no, and retrying cannot
// change that, so it is returned at once. `done` and `partial` are both "the trip
// happened" end states, so they are returned too; only `failed` retries.
//
// Backoff doubles each retry: 1s, 2s, 4s, 8s, 16s. That is 5 retries after the first
// attempt — 6 attempts in all — after which the last `failed` Outcome is returned.
export default async function main(): Promise<Outcome<unknown>> {
  const dest = 'sol_belt';

  let last: Outcome<unknown>;
  let delayMs = 1000;
  for (let attempt = 0; attempt < 6; attempt++) {
    if (attempt > 0) await new Promise(r => setTimeout(r, delayMs));

    last = await tryGoTo(dest);

    if (last.status === 'refused') {
      note(`${dest}: trip refused — not retrying (reason: ${last.why ?? 'unspecified'})`);
      return last;
    }
    if (last.status === 'done' || last.status === 'partial') {
      return last;
    }

    // `failed`: the only status that retries.
    note(`${dest}: attempt ${attempt + 1} of 6 failed (${last.why ?? 'no reason'})`);
    delayMs *= 2;
  }

  // All 6 attempts failed. Hand back the last one; its `why` says what broke.
  return last;
}
```

