import {missions, acceptMission, completeMissions, note, outcome, Outcome} from 'play';

export default async function main() {
  // Board and free slots in one read.
  const board = await missions();
  if (board.status !== 'done') return board;

  const free = (board.detail?.free ?? 0) as number;
  const all = (board.detail?.listings ?? []) as any[];

  // Sort by reward, best first; only consider the ones still available.
  const ranked = all
    .filter(l => l && l.status === 'available' && typeof l.reward === 'number' && l.reward >= 100)
    .sort((a, b) => (b.reward ?? 0) - (a.reward ?? 0));

  // Accept the top ones up to the free slots, stopping at the first non-done accept.
  let accepted = 0;
  for (let i = 0; i < free; i++) {
    const target = ranked[i];
    if (!target) break;
    let res: Outcome<unknown>;
    try {
      res = await acceptMission(target.id);
    } catch (e) {
      res = outcome('accept ' + (target?.name ?? target?.id ?? '?') + ' threw: ' + String(e), 'refused',
        {id: target?.id, error: String(e)});
    }
    if (res.status !== 'done') {
      note(`accept of ${(target?.name ?? target?.id ?? '?')} was ${res.status}: ${res.why}`);
      break;
    }
    accepted++;
  }

  note(`accepted ${accepted} board mission(s) out of ${free} free slot(s)`);

  // Finish what we could, then carry on either way.
  const done = await completeMissions();
  if (done.status !== 'done') {
    note(`completeMissions ended ${done.status}: ${done.why}`);
  }

  return outcome(`accepted ${accepted} board mission(s)`, done.status, {accepted});
}
