export default async function main() {
  let serviceResult: Outcome<unknown> | null = null;

  try {
    const trip = await gatherUntil({poi: 'kepler_belt', base: 'kepler_station'});
    if (trip.status !== 'done') return trip;

    // The trip stows at the base; the take that reached the store is `trip.detail.settled`.
    const copper = (trip.detail?.settled ?? []).find(r => r.item_id === 'copper_ore');
    if (copper) await sell([{item_id: 'copper_ore', quantity: copper.quantity}], {from: 'store'});

    serviceResult = await service();
    await completeMissions(); // a not-done result here is fine
  } catch (e) {
    // whatever happened, keep going to the note below
  }

  const look = await orient();
  note(`current credits: ${look.now?.credits ?? 0}`);

  return serviceResult ?? (await service());
}
